using System.IO;
using System.Diagnostics;
using System.Text;
namespace DanceStudio;
public static class AudioImport {
 public static WaveAudio Load(string path){using var file=File.OpenRead(path);using var reader=new BinaryReader(file);if(file.Length<12||file.Length>512L*1024*1024)throw new InvalidDataException("오디오 파일 크기가 지원 범위를 벗어납니다.");string Tag()=>Encoding.ASCII.GetString(reader.ReadBytes(4));if(Tag()!="RIFF")throw new InvalidDataException("RIFF WAV/XWM 오디오가 아닙니다.");uint declared=reader.ReadUInt32();string kind=Tag();if(kind=="WAVE")return WaveAudio.Load(path);if(kind!="XWMA")throw new InvalidDataException("지원하지 않는 RIFF 오디오 형식입니다.");
  if(declared!=file.Length-8)throw new InvalidDataException("XWM RIFF 길이가 잘못되었습니다.");
  int channels=0,rate=0;uint decodedBytes=0;bool data=false,format=false,index=false;while(file.Position+8<=file.Length){string tag=Tag();uint length=reader.ReadUInt32();long end=file.Position+length;if(end+(length&1)>file.Length)throw new InvalidDataException("XWM 청크 길이가 잘못되었습니다.");if(tag=="fmt "){if(format)throw new InvalidDataException("XWM 형식 청크가 중복되었습니다.");format=true;if(length<16)throw new InvalidDataException("XWM 형식 헤더가 짧습니다.");int codec=reader.ReadUInt16();channels=reader.ReadUInt16();rate=reader.ReadInt32();if(codec!=0x161&&codec!=0x162)throw new NotSupportedException("WMA2/Pro XWM만 지원합니다.");}if(tag=="data"){if(data)throw new InvalidDataException("XWM 오디오 청크가 중복되었습니다.");data=length>0;}if(tag=="dpds"){if(index)throw new InvalidDataException("XWM 표본 인덱스가 중복되었습니다.");index=true;if(length<4||length%4!=0)throw new InvalidDataException("XWM 표본 인덱스가 잘못되었습니다.");uint previous=0;for(long i=0;i<length/4;i++){uint current=reader.ReadUInt32();if(current<previous)throw new InvalidDataException("XWM 표본 인덱스가 감소합니다.");previous=current;}decodedBytes=previous;}file.Position=end+(length&1);}
  if(file.Position!=file.Length)throw new InvalidDataException("XWM에 불완전한 청크가 있습니다.");
  if(!data||channels is <1 or >2||rate is <8000 or >192000||decodedBytes==0||decodedBytes>512L*1024*1024||decodedBytes%(channels*2)!=0)throw new InvalidDataException("XWM의 채널·표본율·디코딩 길이를 확인할 수 없습니다.");
  string? tool=Environment.GetEnvironmentVariable("DANCESTUDIO_FFMPEG");if(string.IsNullOrWhiteSpace(tool))tool=Path.Combine(AppContext.BaseDirectory,"Tools","ffmpeg.exe");if(!File.Exists(tool)){tool=(Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator).Select(x=>Path.Combine(x.Trim('"'),"ffmpeg.exe")).FirstOrDefault(File.Exists);}if(tool==null||!File.Exists(tool))throw new FileNotFoundException("XWM 변환에는 FFmpeg가 필요합니다. 편집기 Tools/ffmpeg.exe 또는 DANCESTUDIO_FFMPEG 환경 변수로 지정하세요. FFmpeg는 별도 설치합니다.");
  string temp=Path.Combine(Path.GetTempPath(),"DanceStudio-"+Guid.NewGuid().ToString("N")+".wav");try{var start=new ProcessStartInfo(tool){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};foreach(string arg in new[]{"-nostdin","-v","error","-f","xwma","-i",Path.GetFullPath(path),"-map","0:a:0","-vn","-acodec","pcm_s16le","-ar",rate.ToString(),"-ac",channels.ToString(),"-f","wav",temp})start.ArgumentList.Add(arg);using var process=Process.Start(start)??throw new IOException("변환기를 실행할 수 없습니다.");var errors=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(120000)){process.Kill(true);throw new IOException("XWM 변환 제한 시간을 초과했습니다.");}string message=errors.GetAwaiter().GetResult();if(process.ExitCode!=0)throw new IOException("XWM 디코딩 실패: "+message[..Math.Min(1500,message.Length)]);var wave=WaveAudio.Load(temp);if(wave.Pcm.Length<decodedBytes)throw new InvalidDataException("XWM 디코딩 결과가 원본 표본 길이보다 짧습니다.");if(wave.Pcm.Length>decodedBytes)wave.Pcm=wave.Pcm[..checked((int)decodedBytes)];wave.RebuildPeaks();wave.Path=Path.GetFullPath(path);return wave;}finally{if(File.Exists(temp))File.Delete(temp);}
 }
}
